562:         private bool CanReceiveFishingTrap(Snapshot s,FishingTrapPhysicalRecord trap,FishingCreatureBodyRecord creature,
563:             FishingReceiveLocationRecord receiver)
564:         {
565:             var receiverSupport=s.Structures.SingleOrDefault(x=>x.Id==receiver.SupportId);
566:             var item=s.PortableEquipment.SingleOrDefault(x=>x.Id==trap.TrapId);
567:             if(receiverSupport==null||receiverSupport.Broken||item==null||!item.OperationalWeightLb.HasValue
568:                 ||receiver.SiteId!=trap.SiteId||receiver.RecoveryPathFeet<1||receiver.RecoveryPathFeet>trap.RecoveryCordFeet)return false;
569:             RuleQuantity mass=new RuleQuantity(0),volume=new RuleQuantity(0);
570:             foreach(var existing in s.FishingTraps.Where(x=>x.Status==FishingTrapPhysicalStatus.Retrieved&&x.ReceivingLocationId==receiver.Id)) {
571:                 var existingItem=s.PortableEquipment.SingleOrDefault(x=>x.Id==existing.TrapId);
572:                 if(existingItem==null||!existingItem.OperationalWeightLb.HasValue)return false;
573:                 mass+=existingItem.OperationalWeightLb.Value;volume+=existing.BodyVolumeCubicFeet;
574:                 var priorAttempt=s.FishingTrapAttempts.Single(x=>x.Id==existing.AttemptId);
575:                 if(priorAttempt.CapturedCreatureId!="") {
576:                     var carried=s.FishingCreatures.SingleOrDefault(x=>x.Id==priorAttempt.CapturedCreatureId&&x.LocationId==receiver.Id);
577:                     if(carried!=null){mass+=carried.MassPounds;volume+=carried.VolumeCubicFeet;}
578:                 }
579:             }
580:             mass+=item.OperationalWeightLb.Value;volume+=trap.BodyVolumeCubicFeet;
581:             if(creature.ContainerId==trap.TrapId){mass+=creature.MassPounds;volume+=creature.VolumeCubicFeet;}
582:             return mass<=receiver.CapacityPounds&&volume<=receiver.CapacityCubicFeet;

